from .repository import put_contact, contact_exists

_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _validate_row(row, index):
    if not isinstance(row, dict):
        raise ValueError(f"row {index} is not an object")
    keys = set(row.keys())
    if keys != _FIELDS:
        missing = sorted(_FIELDS - keys)
        unknown = sorted(str(k) for k in keys - _FIELDS)
        raise ValueError(f"row {index} has missing fields {missing} or unknown fields {unknown}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError(f"row {index} fields must be strings")
    email = email.strip()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError(f"row {index} email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError(f"row {index} email must have nonempty sides around '@'")
    if any(ch.isspace() for ch in email):
        raise ValueError(f"row {index} email must not contain whitespace")
    if not name:
        raise ValueError(f"row {index} name must not be empty")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    validated = []
    seen = set()
    for index, row in enumerate(rows):
        email, name = _validate_row(row, index)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email}")
        seen.add(email)
        validated.append((email, name))
    if not validated:
        return {"inserted": 0, "updated": 0}
    inserted = 0
    updated = 0
    with connection:
        for email, name in validated:
            if contact_exists(connection, email):
                updated += 1
            else:
                inserted += 1
            put_contact(connection, email, name)
    return {"inserted": inserted, "updated": updated}
EOF
